import{_ as r,o as a,c as t,a3 as n}from"./chunks/framework.DBpCFmh2.js";const m=JSON.parse('{"title":"文档处理管道","description":"本技术文档聚焦 RAG 文档处理管道，围绕多格式文档解析、动态路由加载、文本分块策略、预处理流程以及从上传到索引构建的完整链路展开。","frontmatter":{"title":"文档处理管道","description":"本技术文档聚焦 RAG 文档处理管道，围绕多格式文档解析、动态路由加载、文本分块策略、预处理流程以及从上传到索引构建的完整链路展开。"},"headers":[],"relativePath":"RAG-知识检索/文档处理管道/index.md","filePath":"RAG-知识检索/文档处理管道/index.md","lastUpdated":null}'),i={name:"RAG-知识检索/文档处理管道/index.md"};function l(g,e,o,s,c,h){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="文档处理管道" tabindex="-1">文档处理管道 <a class="header-anchor" href="#文档处理管道" aria-label="Permalink to &quot;文档处理管道&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/text.js" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/text.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/pdf.js" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/pdf.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/office.js" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/office.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js" target="_blank" rel="noreferrer">agent/src/rag/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js" target="_blank" rel="noreferrer">agent/src/rag/errors.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js" target="_blank" rel="noreferrer">agent/src/rag/manager.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与容量控制">性能与容量控制</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录端到端示例与扩展机制">附录：端到端示例与扩展机制</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本技术文档聚焦 RAG 文档处理管道，围绕多格式文档解析、动态路由加载、文本分块策略、预处理流程以及从上传到索引构建的完整链路展开。该管道位于 Agent 端的 RAG 子系统，负责将多种来源（本地文件、前端上传、URL）的文档统一解析为纯文本，再经分块、向量化后写入向量存储，同时保留原文备份以支持混合检索与重建。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>RAG 文档处理相关代码集中在 agent/src/rag 下，其中文档解析与分块位于 document 子目录，知识库生命周期与导入编排位于 manager.js，配置与错误类型分别位于 config.js 与 errors.js。</p><pre class="mermaid">graph TB
subgraph &quot;RAG 文档处理&quot;
L[&quot;document/loader.js&lt;br/&gt;按扩展名路由解析器&quot;]
C[&quot;document/chunker.js&lt;br/&gt;段落优先+重叠分块&quot;]
P_TXT[&quot;document/parsers/text.js&lt;br/&gt;文本/BOM清理&quot;]
P_PDF[&quot;document/parsers/pdf.js&lt;br/&gt;PDF 文本提取&quot;]
P_OFFICE[&quot;document/parsers/office.js&lt;br/&gt;Office/PPT/表格解析&quot;]
CFG[&quot;rag/config.js&lt;br/&gt;扩展名路由表/默认参数&quot;]
ERR[&quot;rag/errors.js&lt;br/&gt;RagError 与翻译&quot;]
MGR[&quot;rag/manager.js&lt;br/&gt;导入/分块/向量化/存储编排&quot;]
end
MGR --&gt; L
L --&gt; P_TXT
L --&gt; P_PDF
L --&gt; P_OFFICE
MGR --&gt; C
L --&gt; CFG
MGR --&gt; ERR
</pre><p>图示来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-L76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/text.js#L1-L15" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/text.js#L1-L15</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/pdf.js#L1-L21" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/pdf.js#L1-L21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/office.js#L1-L56" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/office.js#L1-L56</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L749-L897" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L749-L897</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-L76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L1-L70" target="_blank" rel="noreferrer">agent/src/rag/config.js#L1-L70</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L749-L897" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L749-L897</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li>文档加载器（loader.js）：根据文件扩展名动态选择并懒加载对应解析器，返回统一文本与文件名。</li><li>文本分块器（chunker.js）：段落优先断点 + 字符窗口兜底 + 重叠回退，输出带偏移区间的分块。</li><li>解析器族（parsers/*）： <ul><li>text.js：UTF-8 读取并去除 BOM。</li><li>pdf.js：通过 pdf-parse 提取 PDF 文本。</li><li>office.js：docx/xlsx/xls/pptx 等 Office 系列的多后端解析。</li></ul></li><li>配置（config.js）：集中维护扩展名路由表、默认分块参数、模型与批大小等常量。</li><li>错误（errors.js）：定义 RagError 与错误翻译工具，便于上层响应层国际化。</li><li>管理器（manager.js）：封装知识库生命周期、导入入口（文本/文件/URL）、分块、向量化、存储与备份、重建与恢复。</li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-L76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/text.js#L1-L15" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/text.js#L1-L15</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/pdf.js#L1-L21" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/pdf.js#L1-L21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/office.js#L1-L56" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/office.js#L1-L56</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L1-L70" target="_blank" rel="noreferrer">agent/src/rag/config.js#L1-L70</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L749-L897" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L749-L897</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>下图展示从“文档进入”到“索引构建”的端到端流程，包括解析、分块、向量化、存储与备份。</p><pre class="mermaid">sequenceDiagram
participant Client as &quot;调用方&quot;
participant Manager as &quot;RagManager&quot;
participant Loader as &quot;loadDocument&quot;
participant Parser as &quot;具体解析器&quot;
participant Chunker as &quot;chunkText&quot;
participant Embed as &quot;EmbeddingProvider&quot;
participant Store as &quot;VectraStore&quot;
Client-&gt;&gt;Manager : ingestFile / ingestUrl / ingestText
Manager-&gt;&gt;Loader : loadDocument(filePath)
Loader-&gt;&gt;Parser : parse(filePath)
Parser--&gt;&gt;Loader : text
Loader--&gt;&gt;Manager : {text, fileName}
Manager-&gt;&gt;Chunker : chunkText(text, options)
Chunker--&gt;&gt;Manager : chunks[{text,startPos,endPos}]
Manager-&gt;&gt;Embed : embedDocuments(chunks)
Embed--&gt;&gt;Manager : embeddings[]
Manager-&gt;&gt;Store : upsertChunks(documentId, chunks, embeddings, metadata)
Manager-&gt;&gt;Manager : _saveDocumentBackup(...)
Manager--&gt;&gt;Client : {documentId, name, chunkCount}
</pre><p>图示来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L749-L897" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L749-L897</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L38-L48" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L38-L48</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L31-L74" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L31-L74</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="文档加载器与解析器路由" tabindex="-1">文档加载器与解析器路由 <a class="header-anchor" href="#文档加载器与解析器路由" aria-label="Permalink to &quot;文档加载器与解析器路由&quot;">​</a></h3><ul><li>扩展名路由表由 config.js 的 PARSER_ROUTES 维护，loader.js 据此判断是否受支持并动态选择解析器名称。</li><li>解析器采用按需 import，仅实际使用的格式才加载对应依赖，降低冷启动成本。</li><li>不支持的扩展名会抛出 RagError(&#39;unsupportedFormat&#39;)，便于上层统一处理。</li></ul><pre class="mermaid">flowchart TD
A[&quot;收到 filePath&quot;] --&gt; B[&quot;ext = extname(filePath).toLowerCase()&quot;]
B --&gt; C{&quot;ext 在 PARSER_ROUTES ?&quot;}
C -- 否 --&gt; E[&quot;抛出 RagError(&#39;unsupportedFormat&#39;)&quot;]
C -- 是 --&gt; D[&quot;mod = await PARSERS[name]()&quot;]
D --&gt; F[&quot;text = await mod.parse(filePath)&quot;]
F --&gt; G[&quot;返回 {text, fileName}&quot;]
</pre><p>图示来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L21-L48" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L21-L48</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li></ul><h3 id="文本分块策略" tabindex="-1">文本分块策略 <a class="header-anchor" href="#文本分块策略" aria-label="Permalink to &quot;文本分块策略&quot;">​</a></h3><ul><li>自然断点优先级：优先在段落或句子边界切分，避免截断语义。</li><li>字符窗口兜底：当找不到断点时，按 chunkSize 切分。</li><li>重叠回退：下一块起点回退 overlap 字符，防止上下文断裂；同时保证 next &gt; start 避免死循环。</li><li>安全上限：超过 CHUNK_SIZE_WARN_LIMIT 会告警，避免被模型静默截断。</li></ul><pre class="mermaid">flowchart TD
S[&quot;开始&quot;] --&gt; N[&quot;规范化换行&quot;]
N --&gt; W[&quot;计算 chunkSize/overlap钳制范围&quot;]
W --&gt; L{&quot;pos &lt; n ?&quot;}
L -- 否 --&gt; END[&quot;结束&quot;]
L -- 是 --&gt; SKIP[&quot;跳过空白起始&quot;]
SKIP --&gt; END_POS[&quot;end = min(start+chunkSize, n)&quot;]
END_POS --&gt; BRK{&quot;未到文末？&quot;}
BRK -- 是 --&gt; FIND[&quot;在后半段寻找最近断点&quot;]
FIND --&gt; ADJ[&quot;若找到则 end=breakAt&quot;]
BRK -- 否 --&gt; NEXT_STEP[&quot;继续&quot;]
ADJ --&gt; NEXT_STEP[&quot;取 slice(start,end).trim()&quot;]
NEXT_STEP --&gt; PUSH{&quot;是否为空？&quot;}
PUSH -- 否 --&gt; ADD[&quot;加入 chunks&quot;]
PUSH -- 是 --&gt; NOOP[&quot;跳过&quot;]
ADD --&gt; CHECKEND{&quot;end &gt;= n ?&quot;}
NOOP --&gt; CHECKEND
CHECKEND -- 是 --&gt; END
CHECKEND -- 否 --&gt; OVERLAP[&quot;next = max(end-overlap, start+1)&quot;]
OVERLAP --&gt; UPDATE[&quot;pos = next; 回到 L&quot;]
</pre><p>图示来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L10-L74" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L10-L74</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L37-L44" target="_blank" rel="noreferrer">agent/src/rag/config.js#L37-L44</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L37-L44" target="_blank" rel="noreferrer">agent/src/rag/config.js#L37-L44</a></li></ul><h3 id="解析器实现要点" tabindex="-1">解析器实现要点 <a class="header-anchor" href="#解析器实现要点" aria-label="Permalink to &quot;解析器实现要点&quot;">​</a></h3><ul><li>文本类（text.js）：以 UTF-8 读取，去除首字节 BOM，避免影响 embedding 质量。</li><li>PDF（pdf.js）：通过 pdf-parse 提取文本；因 CJS 特性使用 createRequire 加载。</li><li>Office（office.js）： <ul><li>docx → mammoth 提取纯文本。</li><li>xlsx/xls → xlsx 逐 sheet 转 CSV，保留行列结构。</li><li>pptx 及其他 → officeparser 通用解析。</li></ul></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/text.js#L1-L15" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/text.js#L1-L15</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/pdf.js#L1-L21" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/pdf.js#L1-L21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/office.js#L1-L56" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/office.js#L1-L56</a></li></ul><h3 id="文档预处理与元数据" tabindex="-1">文档预处理与元数据 <a class="header-anchor" href="#文档预处理与元数据" aria-label="Permalink to &quot;文档预处理与元数据&quot;">​</a></h3><ul><li>编码处理：文本解析器显式处理 UTF-8 BOM；URL 链路通过 decodeBytes 按 contentType 解码（兼容 GBK 站点）。</li><li>特殊字符清理：分块前对换行进行规范化，避免 \\r\\n 混用导致断点异常。</li><li>表格数据提取：Excel 转为 CSV 文本，保留行列结构，利于检索理解。</li><li>元数据保留： <ul><li>用户 metadata 先展开，系统键（documentName/source/createdAt）最后写入，确保不被覆盖。</li><li>原文备份包含 id/name/text/source/metadata/chunkCount/createdAt，供 BM25 与重建使用。</li></ul></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/text.js#L10-L14" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/text.js#L10-L14</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L34-L36" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L34-L36</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/parsers/office.js#L24-L33" target="_blank" rel="noreferrer">agent/src/rag/document/parsers/office.js#L24-L33</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L868-L879" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L868-L879</a></li></ul><h3 id="端到端导入流程-文件-url-文本" tabindex="-1">端到端导入流程（文件/URL/文本） <a class="header-anchor" href="#端到端导入流程-文件-url-文本" aria-label="Permalink to &quot;端到端导入流程（文件/URL/文本）&quot;">​</a></h3><ul><li>文件导入： <ul><li>本地路径：走沙箱校验（allowedPaths + 硬阻止清单），通过后交由 loader 解析。</li><li>base64 上传：体积预检后落临时文件，解析后删除。</li></ul></li><li>URL 导入： <ul><li>安全抓取（重定向校验、私网拦截、响应体上限）。</li><li>HTML → htmlToText；PDF → 临时文件 + loader；其他 text/* → 解码为文本。</li></ul></li><li>统一入库： <ul><li>分块 → 批量向量化（含维度校验）→ 事务写入 VectraStore → 原文备份 → 更新注册表计数。</li></ul></li></ul><pre class="mermaid">sequenceDiagram
participant API as &quot;调用方&quot;
participant M as &quot;RagManager&quot;
participant FS as &quot;文件系统/网络&quot;
participant L as &quot;loadDocument&quot;
participant C as &quot;chunkText&quot;
participant E as &quot;EmbeddingProvider&quot;
participant V as &quot;VectraStore&quot;
API-&gt;&gt;M : ingestFile(path|contentBase64)
M-&gt;&gt;FS : 沙箱检查/写临时文件
M-&gt;&gt;L : parse(filePath)
L--&gt;&gt;M : text
M-&gt;&gt;C : chunkText(text)
C--&gt;&gt;M : chunks
M-&gt;&gt;E : embedDocuments(chunks)
E--&gt;&gt;M : embeddings
M-&gt;&gt;V : upsertChunks(...)
M-&gt;&gt;M : _saveDocumentBackup(...)
M--&gt;&gt;API : {documentId, name, chunkCount}
</pre><p>图示来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L749-L897" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L749-L897</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L38-L48" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L38-L48</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L31-L74" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L31-L74</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L749-L897" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L749-L897</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li>loader.js 依赖 config.js 的 PARSER_ROUTES，决定解析器名称；运行时按需 import 具体解析器模块。</li><li>chunker.js 依赖 config.js 的 CHUNK_SIZE_WARN_LIMIT 做安全告警。</li><li>manager.js 组合 loader、chunker、embedding provider、VectraStore，并负责进度上报与错误包装。</li><li>errors.js 提供 RagError 与 translateRagError，用于上层响应层国际化。</li></ul><pre class="mermaid">graph LR
CFG[&quot;config.js&quot;] --&gt; LDR[&quot;loader.js&quot;]
CFG --&gt; CHK[&quot;chunker.js&quot;]
LDR --&gt; TXT[&quot;parsers/text.js&quot;]
LDR --&gt; PDF[&quot;parsers/pdf.js&quot;]
LDR --&gt; OFF[&quot;parsers/office.js&quot;]
MGR[&quot;manager.js&quot;] --&gt; LDR
MGR --&gt; CHK
MGR --&gt; ERR[&quot;errors.js&quot;]
</pre><p>图示来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-L76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L1-L70" target="_blank" rel="noreferrer">agent/src/rag/config.js#L1-L70</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L749-L897" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L749-L897</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L1-L30</a></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-L76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L1-L70" target="_blank" rel="noreferrer">agent/src/rag/config.js#L1-L70</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L749-L897" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L749-L897</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L1-L30</a></li></ul><h2 id="性能与容量控制" tabindex="-1">性能与容量控制 <a class="header-anchor" href="#性能与容量控制" aria-label="Permalink to &quot;性能与容量控制&quot;">​</a></h2><ul><li>分块大小与重叠：默认 chunkSize=400、overlap=80，兼顾中文 token 上限与安全边界；超过 500 字符触发告警。</li><li>批大小：EMBED_BATCH_SIZE=10，适配部分平台单次批量上限。</li><li>导入体积限制： <ul><li>文本导入上限 10MB。</li><li>文件上传上限 50MB（base64 长度近似换算）。</li></ul></li><li>内存保护：超大内容在解析/分块/向量化前快速失败，避免全量驻留内存。</li><li>进度监控：导入各阶段（parsing/chunking/embedding/storing/done/error）均上报进度快照，供前端轮询。</li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L31-L41" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L31-L41</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L37-L54" target="_blank" rel="noreferrer">agent/src/rag/config.js#L37-L54</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L42-L45" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L42-L45</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L723-L789" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L723-L789</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L849-L897" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L849-L897</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><ul><li>不支持的文件格式： <ul><li>现象：抛出 RagError(&#39;unsupportedFormat&#39;)。</li><li>排查：确认扩展名是否在 PARSER_ROUTES 中；必要时添加新路由。</li></ul></li><li>内容为空： <ul><li>现象：emptyContent / emptyDocument / urlNoContent。</li><li>排查：检查解析结果是否为空；URL 场景注意反爬壳页或无文本层 PDF。</li></ul></li><li>维度不匹配： <ul><li>现象：embeddingDimensionMismatch。</li><li>排查：核对 embeddingConfig.dimensions 与实际模型输出维度是否一致。</li></ul></li><li>重建中断恢复： <ul><li>现象：进程重启后出现 .rebuild_* 目录或 rebuild_manifest.json。</li><li>行为：自动收敛（完成换入/补提交/回滚旧索引/清理残留）。</li></ul></li><li>权限与密钥： <ul><li>collections.json 落盘权限 0o600；apiKey 落盘前混淆，内存明文。</li></ul></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L38-L47" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L38-L47</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L723-L897" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L723-L897</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L434-L640" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L434-L640</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/errors.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/errors.js#L1-L30</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>该 RAG 文档处理管道通过“扩展名路由 + 按需解析器 + 段落优先分块 + 批量向量化 + 原子重建”的组合，实现了多格式文档的统一接入与高可靠索引构建。其设计强调可观测性（进度上报）、安全性（沙箱/尺寸限制/权限）与可恢复性（重建清单与恢复逻辑），适合在生产环境中稳定运行。</p><h2 id="附录-端到端示例与扩展机制" tabindex="-1">附录：端到端示例与扩展机制 <a class="header-anchor" href="#附录-端到端示例与扩展机制" aria-label="Permalink to &quot;附录：端到端示例与扩展机制&quot;">​</a></h2><h3 id="端到端示例-上传到索引构建" tabindex="-1">端到端示例（上传到索引构建） <a class="header-anchor" href="#端到端示例-上传到索引构建" aria-label="Permalink to &quot;端到端示例（上传到索引构建）&quot;">​</a></h3><p>以下示例描述从“前端上传文件”到“索引构建完成”的调用序列，包含错误处理与进度监控的关键节点。</p><pre class="mermaid">sequenceDiagram
participant UI as &quot;前端/调用方&quot;
participant M as &quot;RagManager&quot;
participant L as &quot;loadDocument&quot;
participant C as &quot;chunkText&quot;
participant E as &quot;EmbeddingProvider&quot;
participant V as &quot;VectraStore&quot;
UI-&gt;&gt;M : ingestFile({fileName, contentBase64})
M-&gt;&gt;M : 体积预检≈ base64*3/4
M-&gt;&gt;M : 写临时文件
M-&gt;&gt;L : loadDocument(tmpPath)
L--&gt;&gt;M : {text, fileName}
M-&gt;&gt;C : chunkText(text, collection.chunkConfig)
C--&gt;&gt;M : chunks
M-&gt;&gt;E : embedDocuments(chunks)
E--&gt;&gt;M : embeddings
M-&gt;&gt;V : upsertChunks(documentId, chunks, embeddings, metadata)
M-&gt;&gt;M : _saveDocumentBackup(...)
M--&gt;&gt;UI : {documentId, name, chunkCount}
Note over M : 全程上报 phase=parsing/chunking/embedding/storing/done/error
</pre><p>图示来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L749-L897" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L749-L897</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L38-L48" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L38-L48</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L31-L74" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L31-L74</a></li></ul><h3 id="扩展新文档格式的步骤" tabindex="-1">扩展新文档格式的步骤 <a class="header-anchor" href="#扩展新文档格式的步骤" aria-label="Permalink to &quot;扩展新文档格式的步骤&quot;">​</a></h3><ul><li>新增解析器： <ul><li>在 parsers/ 下新增解析模块，实现统一的 parse(filePath) 接口。</li></ul></li><li>注册路由： <ul><li>在 config.js 的 PARSER_ROUTES 中添加扩展名到解析器名称的映射。</li></ul></li><li>可选优化： <ul><li>如需懒加载，可在 loader.js 的 PARSERS 映射中增加对应的动态 import。</li></ul></li><li>验证： <ul><li>使用 isSupportedFile 与 supportedExtensions 校验扩展名。</li><li>通过 ingestFile 传入测试文件，观察 parsing → chunking → embedding → storing → done 的进度。</li></ul></li></ul><p>章节来源</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L8-L14" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L8-L14</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li></ul>`,79)])])}const b=r(i,[["render",l]]);export{m as __pageData,b as default};
